<template>
  <Head><title>Documents - MaterialTrack</title></Head>
  <main class="p-6"><div class="max-w-7xl mx-auto">
    <div class="flex justify-between items-center mb-5"><div><h1 class="text-2xl font-bold">Document Management</h1><p class="text-sm text-gray-500">{{ currentFolder ? currentFolder.name : 'Root folder' }}</p></div><Link v-if="currentFolder" href="/apps/documents" class="mtx-btn mtx-btn-secondary">Root</Link></div>
    <div class="grid grid-cols-1 lg:grid-cols-3 gap-6">
      <section class="mtx-card"><div class="mtx-card-header"><span class="mtx-card-title">New Folder</span></div><div class="mtx-card-body"><form @submit.prevent="createFolder"><div class="mtx-field"><label class="mtx-label">Folder Name *</label><input v-model="folderForm.name" class="mtx-input" required></div><div class="mtx-field"><label class="mtx-label">Department</label><select v-model="folderForm.department_id" class="mtx-input"><option value="">All departments</option><option v-for="department in departments" :key="department.id" :value="department.id">{{ department.name }}</option></select></div><button class="mtx-btn mtx-btn-primary w-full" :disabled="folderForm.processing">Create Folder</button></form></div></section>
      <section class="mtx-card"><div class="mtx-card-header"><span class="mtx-card-title">Upload Document</span></div><div class="mtx-card-body"><form @submit.prevent="upload"><div class="mtx-field"><label class="mtx-label">Title *</label><input v-model="documentForm.title" class="mtx-input" required></div><div class="mtx-field"><label class="mtx-label">File *</label><input type="file" @input="documentForm.file = $event.target.files[0]" class="mtx-input" required></div><div class="mtx-field"><label class="mtx-label">Description</label><textarea v-model="documentForm.description" class="mtx-textarea"></textarea></div><button class="mtx-btn mtx-btn-primary w-full" :disabled="documentForm.processing">Upload</button></form></div></section>
      <section class="mtx-card"><div class="mtx-card-header"><span class="mtx-card-title">Storage</span></div><div class="mtx-card-body text-sm text-gray-600">File maximum: 10 MB.<br>Documents stored in Laravel public disk.</div></section>
    </div>
    <section class="mtx-card mt-6"><div class="mtx-card-header"><span class="mtx-card-title">Contents</span></div><div class="mtx-card-body"><div class="grid grid-cols-2 md:grid-cols-5 gap-3"><Link v-for="folder in folders" :key="folder.id" :href="`/apps/documents?folder_id=${folder.id}`" class="border rounded p-4 hover:bg-gray-50"><div class="text-2xl">??</div><b class="block truncate">{{ folder.name }}</b><small>{{ folder.department?.name || 'All departments' }}</small></Link></div><table class="min-w-full text-sm mt-5"><tbody><tr v-for="document in documents" :key="document.id" class="border-b"><td class="p-3">?? <b>{{ document.title }}</b><small class="ml-2 text-gray-500">{{ document.file_type }} · {{ Math.ceil(document.file_size / 1024) }} KB</small></td><td class="p-3">{{ document.uploader.name }}</td><td class="p-3 text-right"><a :href="`/apps/documents/${document.id}/download`" class="text-primary mr-3">Download</a><button @click="remove(document.id)" class="text-red-600">Delete</button></td></tr><tr v-if="!folders.length && !documents.length"><td class="p-6 text-center text-gray-500">Folder empty.</td></tr></tbody></table></div></section>
  </div></main>
</template>
<script>
import LayoutApp from '@/Layouts/App.vue'; import { Head, Link, router, useForm } from '@inertiajs/vue3';
export default {layout:LayoutApp,components:{Head,Link},props:{folders:Array,documents:Array,currentFolder:Object,departments:Array},setup(props){const folderForm=useForm({name:'',parent_id:props.currentFolder?.id||'',department_id:''}),documentForm=useForm({title:'',file:null,dms_folder_id:props.currentFolder?.id||'',description:''});return {folderForm,documentForm,createFolder:()=>folderForm.post('/apps/documents/folders',{onSuccess:()=>folderForm.reset('name')}),upload:()=>documentForm.post('/apps/documents',{forceFormData:true,onSuccess:()=>documentForm.reset()}),remove:(id)=>{if(confirm('Delete document?'))router.delete(`/apps/documents/${id}`)}}}}
</script>
